exercise.solution:
CREATE TABLE lab_l09_posts (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL
);

CREATE TABLE lab_l09_comments (
  id SERIAL PRIMARY KEY,
  title VARCHAR(200) NOT NULL,
  post_id INTEGER NOT NULL REFERENCES lab_l09_posts(id) ON DELETE CASCADE
);

